    def __init__(self):
        self._display = None

    def enable_virtual_display(self, width=1920, height=1280):
        """
        This keyword is used to enable virtual display - with it enabled browser
        window will not be displayed on screen.

        In order for this functionality to work correctly this keyword must to be
        called before `Login` keyword is called (which would spawn browser window).

        Please make sure "xvfb" service is installed on the environment.

        :param width: int, width of browser
        :param height: int, height of browser
        """
        self._deprecated_report()
        self._display = Display(visible=0, size=(width, height))
        self._display.start()

    def disable_virtual_display(self):
        """
        This keyword is used to disable virtual display.
        Please make sure to call this method at the end of test if you've call "enable_virtual_display"
        """
        self._deprecated_report()
        self._display.stop()

